import text from '../../../host/data/credits.tsv?raw';

// The open-source software the web and desktop apps ship, for their About dialog (about.ts). The
// file is the one the native apps compile in (host/credits.hpp), generated by
// tools/gen/credits.mjs, read by the same rules.

/**
 * DiaDraw's own licence and copyright line (the repository's LICENSE file; host/about.hpp). The
 * tests check them against LICENSE.
 */
export const LICENSE = 'MIT License';
export const COPYRIGHT = 'Copyright © 2026 Andriy Mykulyak';
export const PROJECT_URL = 'https://github.com/mykulyak/diadraw';
/** DiaDraw's licence on GitHub. */
export const LICENSE_URL = `${PROJECT_URL}/blob/main/LICENSE`;
/** Every credit, with what each one is used for: the website's Credits page. */
export const CREDITS_URL = `${PROJECT_URL}/blob/main/docs/credits.md`;

/** One credited component. */
export interface Credit {
  /** `miniz` */
  readonly name: string;
  /** `3.0.2`, or how the version is chosen (`system`). */
  readonly version: string;
  /** `MIT`: an SPDX expression where there is one. */
  readonly license: string;
  /** Its home page. */
  readonly url: string;
  /** The apps that ship it: `gtk`, `macos`, `winui`, `web`, `desktop`. */
  readonly apps: readonly string[];
}

/** `s` without ASCII blanks at either end, as the C++ reader trims (host/credits.cpp). */
const trimAscii = (s: string): string => s.replace(/^[ \t\r\n]+|[ \t\r\n]+$/g, '');

/**
 * Credits in the file's format: name, version, licence, address and the apps (separated by
 * spaces), separated by tabs, one per line, with `//` comment lines. Fields lose ASCII blanks at
 * either end. Lines without a name and those with fewer than five fields are left out.
 */
export function parseCredits(source: string): Credit[] {
  const credits: Credit[] = [];
  for (const raw of source.split('\n')) {
    const line = raw.replace(/\r$/, '');
    const trimmed = trimAscii(line);
    if (!trimmed || trimmed.startsWith('//')) continue;
    const fields = line.split('\t').map(trimAscii);
    if (fields.length < 5 || !fields[0]) continue;
    const [name, version, license, url, apps] = fields as [string, string, string, string, string];
    credits.push({ name, version, license, url, apps: apps.split(' ').filter(Boolean) });
  }
  return credits;
}

/** The credits of one app (`web` or `desktop`), in the file's order (by name). */
export function creditsFor(app: string, credits: readonly Credit[] = builtIn()): Credit[] {
  return credits.filter((c) => c.apps.includes(app));
}

let cached: Credit[] | undefined;
const builtIn = (): Credit[] => (cached ??= parseCredits(text));
